import Link from "next/link";
import { searchPoliticians } from "@/lib/politicians";

export const dynamic = "force-dynamic";

export default async function HomePage({
  searchParams,
}: {
  searchParams: { q?: string };
}) {
  const query = searchParams.q ?? "";
  const results = await searchPoliticians(query);

  return (
    <>
      <section className="hero">
        <h1>Politician Career Histories</h1>
        <p>Search by name, office, state, or party.</p>
        <form className="search-form" action="/" method="get">
          <input
            className="search-input"
            type="text"
            name="q"
            placeholder="Search politicians…"
            defaultValue={query}
            autoFocus
          />
          <button className="btn" type="submit">
            Search
          </button>
        </form>
      </section>

      <div className="container">
        {results.length === 0 ? (
          <p className="empty">
            {query
              ? `No politicians found for “${query}”.`
              : "No politicians yet."}
          </p>
        ) : (
          <div className="results">
            {results.map((p) => (
              <Link key={p.id} href={`/politicians/${p.slug}`} className="card">
                <h3>{p.name}</h3>
                <div className="meta">
                  {[p.current_office, p.party, p.state]
                    .filter(Boolean)
                    .join(" · ")}
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </>
  );
}

export default function AboutPage() {
  return (
    <div className="container">
      <h1 className="section-title">About Mapachusetts</h1>
      <p className="bio">
        Mapachusetts is a simple directory for searching politicians and viewing
        their career history. Each politician has their own page with a timeline
        of the offices and roles they have held.
      </p>
      <p className="bio">
        Data is stored in Supabase (Postgres). Replace the sample records with
        your own via the Supabase dashboard or a data import.
      </p>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { getAllSlugs, getPoliticianBySlug } from "@/lib/politicians";
import type { CareerEntry } from "@/lib/types";

export const dynamic = "force-dynamic";

// Pre-generate a static page per politician at build time.
export async function generateStaticParams() {
  const slugs = await getAllSlugs();
  return slugs.map((slug) => ({ slug }));
}

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}): Promise<Metadata> {
  const politician = await getPoliticianBySlug(params.slug);
  if (!politician) return { title: "Not found — Mapachusetts" };
  return {
    title: `${politician.name} — Mapachusetts`,
    description:
      politician.bio ?? `Career history for ${politician.name}.`,
  };
}

export default async function PoliticianPage({
  params,
}: {
  params: { slug: string };
}) {
  const politician = await getPoliticianBySlug(params.slug);
  if (!politician) notFound();

  const career: CareerEntry[] = Array.isArray(politician.career_history)
    ? politician.career_history
    : [];

  return (
    <div className="container">
      <Link href="/" className="back-link">
        ← Back to search
      </Link>

      <div className="profile-header">
        <h1>{politician.name}</h1>
        <div className="badges">
          {politician.current_office && (
            <span className="badge">{politician.current_office}</span>
          )}
          {politician.party && <span className="badge">{politician.party}</span>}
          {politician.state && <span className="badge">{politician.state}</span>}
        </div>
      </div>

      {politician.bio && <p className="bio">{politician.bio}</p>}

      <h2 className="section-title">Career History</h2>
      {career.length === 0 ? (
        <p className="empty">No career history recorded.</p>
      ) : (
        <div className="timeline">
          {career.map((entry, i) => (
            <div className="timeline-item" key={i}>
              <div className="timeline-period">{entry.period}</div>
              <div className="timeline-role">{entry.role}</div>
              {entry.notes && (
                <div className="timeline-notes">{entry.notes}</div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import Link from "next/link";

export default function NotFound() {
  return (
    <div className="container">
      <h1 className="section-title">Not found</h1>
      <p className="bio">That politician could not be found.</p>
      <Link href="/" className="btn">
        Back to search
      </Link>
    </div>
  );
}

